// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 funding) public {
        funding = bound(funding, 1, 1 ether);

        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        vm.deal(address(this), funding);
        (bool s, ) = address(c).call{value: funding}("");
        require(s);

        vm.deal(caller, 1 wei);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != address(this)) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}
